questionResults.sql:
SELECT designation, full_name, diameter_est_km, moid_ld FROM asteroids
WHERE is_neo = 1 AND diameter_est_km > 1000 AND moid_ld < 1
ORDER BY diameter_est_km DESC LIMIT 25;

